import pathlib,json,re,subprocess
repo=pathlib.Path('/workspace/calcumint-worker3-recovery');out=pathlib.Path('/tmp/worker3-mandatory-queue-profile12d');summary=json.loads((out/'summary.json').read_text());current=(repo/'tests/parallel-source-20261110/current.test.mjs').read_text();baseline=subprocess.check_output(['git','show',summary['head']+':tests/parallel-source-20261110/current.test.mjs']).decode()
block=current.split(' const files=',1)[1].split(';\n const run=',1)[0];files=[(p,int(n)) for p,n in re.findall(r"\['([^']+)',(\d+)\]",block)];fresh=(repo/'tests/next-engineering-20261115/source-fresh-git-mandatory-children.mjs').read_text();files.extend((p,int(n)) for p,n in re.findall(r"\['([^']+)',(\d+)\]",fresh));assert len(files)==40
priority=lambda source:re.findall(r"'([^']+)'",re.search(r' const priority=(\[[^\n]+\]);',source).group(1))
old=priority(baseline);new=priority(current);assert len(old)==5 and len(new)==11
normalize=lambda p:p if p.startswith('tests/') else 'tests/completion-wave-20261113/'+p;durations={r['label']:r['wallMS'] for r in summary['rows']};cold=next(x for x in files if x[0]=='source-app-stage5-availability.test.mjs');scope=next(x for x in files if x[0]=='tests/milestone100-20261114/source-stage8-authority-scope.test.mjs');heavy=[next(x for x in files if x[0]==p) for p in ['tests/milestone100-20261114/source-stage8-runtime-auxiliary.test.mjs','source-authority-preload.test.mjs']];companion=[x for x in files if x!=cold and x!=scope and x not in heavy]
def simulate(order):
 rank=lambda x:order.index(x[0]) if x[0] in order else len(order);pool=sorted(heavy+companion,key=rank);workers=[0.0,0.0];rows=[]
 for file,count in pool:
  lane=min(range(2),key=lambda i:workers[i]);began=workers[lane];duration=durations[normalize(file)];workers[lane]+=duration;rows.append(dict(file=normalize(file),lane=lane,startMS=began,endMS=workers[lane],wallMS=duration))
 exclusive=sum(durations[normalize(x[0])] for x in [cold,scope]);return {'priority':order,'exclusiveMS':exclusive,'simulatedPoolWallMS':max(workers),'simulatedTotalMS':exclusive+max(workers),'lanesMS':workers,'schedule':rows}
a,b=simulate(old),simulate(new);result={'head':summary['head'],'workingPrioritySHA256':summary['prioritySHA256'],'oldFivePriority':a,'newElevenPriority':b,'simulatedReductionMS':a['simulatedTotalMS']-b['simulatedTotalMS'],'limitations':'OFFLINE TRACE SIMULATION ONLY: reuses durations measured under new schedule. Durations can change with companion CPU/I/O, so this is not a measured causal scheduling gain or acceptance evidence. Exact queue still runs all40commands with original30second child limits.','qualified':False};(out/'schedule-simulation.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps({k:v for k,v in result.items() if k not in ['oldFivePriority','newElevenPriority']}));print('old5',a['simulatedTotalMS'],'new11',b['simulatedTotalMS'])
